function affineCipher(text, a, b, decrypt = false) {
  if (typeof text !== "string" || !/^[A-Z ]*$/.test(text))
    throw new TypeError("Use uppercase A-Z and spaces only");
  if (!Number.isSafeInteger(a) || !Number.isSafeInteger(b) ||
      typeof decrypt !== "boolean") throw new TypeError("Invalid key or mode");
  const mod = x => ((x % 26) + 26) % 26;
  a = mod(a); b = mod(b);
  let inverse = 0;
  for (let u = 1; u < 26; u++) if ((a * u) % 26 === 1) inverse = u;
  if (inverse === 0) throw new RangeError("a must be relatively prime to 26");
  return Array.from(text, ch => {
    if (ch === " ") return ch;
    const value = ch.charCodeAt(0) - 65;
    const out = decrypt ? mod(inverse * (value - b)) : mod(a * value + b);
    return String.fromCharCode(65 + out);
  }).join("");
}

function permuteBlocks(text, order, decrypt = false) {
  if (typeof text !== "string" || !/^[A-Z]*$/.test(text))
    throw new TypeError("Use uppercase letters without spaces");
  if (!Array.isArray(order) || order.length < 1 || order.length > 1000 ||
      typeof decrypt !== "boolean") throw new TypeError("Invalid order or mode");
  const width = order.length;
  if (!Array.from(order).every(v => Number.isInteger(v) && v >= 1 && v <= width) ||
      new Set(order).size !== width) throw new RangeError("Use a permutation of 1 through width");
  if (text.length % width !== 0) throw new RangeError("Supply full blocks; keep padding metadata separately");
  let result = "";
  for (let start = 0; start < text.length; start += width) {
    const out = Array(width);
    for (let i = 0; i < width; i++) {
      if (decrypt) out[order[i] - 1] = text[start + i];
      else out[i] = text[start + order[i] - 1];
    }
    result += out.join("");
  }
  return result;
}

function encodePairs(text) {
  if (typeof text !== "string" || !/^(?:[A-Z]{2})*$/.test(text))
    throw new TypeError("Supply an even number of uppercase letters");
  const blocks = [];
  for (let i = 0; i < text.length; i += 2)
    blocks.push(BigInt(100 * (text.charCodeAt(i) - 65) + text.charCodeAt(i + 1) - 65));
  return blocks;
}
function decodePairs(blocks) {
  if (!Array.isArray(blocks)) throw new TypeError("Supply an array of BigInt blocks");
  return Array.from(blocks, block => {
    if (typeof block !== "bigint") throw new TypeError("Use BigInt blocks");
    if (block < 0n || block > 2525n || block / 100n > 25n || block % 100n > 25n)
      throw new RangeError("Each two-digit letter code must be 00 through 25");
    return String.fromCharCode(65 + Number(block / 100n), 65 + Number(block % 100n));
  }).join("");
}

function toyRsaKey(p, q, e) {
  if (![p, q, e].every(x => typeof x === "bigint")) throw new TypeError("Use BigInt inputs");
  if (p < 2n || q < 2n || p > 10000n || q > 10000n || p === q ||
      !isPrime(p) || !isPrime(q)) throw new RangeError("Use distinct primes at most 10000");
  const n = p * q, phi = (p - 1n) * (q - 1n);
  if (e <= 1n || e >= phi) throw new RangeError("Require 1 < e < phi");
  const d = inverseMod(e, phi);
  if (d === null) throw new RangeError("e must be relatively prime to phi");
  return { n, e, d, phi };
}
function rsaBlock(value, exponent, n) {
  if (![value, exponent, n].every(x => typeof x === "bigint")) throw new TypeError("Use BigInt inputs");
  if (n <= 1n || exponent <= 0n || value < 0n || value >= n)
    throw new RangeError("Require n > 1, exponent > 0, and 0 <= value < n");
  return modPower(value, exponent, n);
}
